SELECT d.id::text,d.title,d.rationale,d.status,d.decided_at::text,s.path source_path,l.root_path source_root_path,s.freshness_status source_freshness,(d.source_document_id IS NOT NULL AND (s.freshness_status IS DISTINCT FROM 'current' OR d.source_revision_id IS DISTINCT FROM v.id)) is_stale FROM decisions d JOIN projects p ON p.id=d.project_id LEFT JOIN source_documents s ON s.id=d.source_document_id LEFT JOIN repository_locations l ON l.id=s.repository_location_id LEFT JOIN document_revisions v ON v.source_document_id=s.id AND v.is_current WHERE p.slug=$1 AND d.superseded_by_id IS NULL ORDER BY (d.status='validated' AND NOT (d.source_document_id IS NOT NULL AND (s.freshness_status IS DISTINCT FROM 'current' OR d.source_revision_id IS DISTINCT FROM v.id))) DESC,d.decided_at DESC LIMIT $2
